  SetSpeed(14);
  int step = 0;
}

public static void Tick(int dt) {
  ControlSequence(dt);
}

public static void ControlSequence(int dt) {
  if (step == 0 && GetAngle() < 134) {
    RotateTo(135);
    return;
  }
  if (step == 0) { step = 1; }
  if (step == 1 && GetHeight() < 1.5) {
    LiftTo(1.5);
    return;
  }
  if (step == 1) { step = 2; }
  if (step == 2 && GetAngle() > 46) {
    RotateTo(45);
    return;
  }
  if (step == 2) { step = 3; }
  if (step == 3 && GetHeight() < 2.0) {
    LiftTo(2.0);
    return;
  }
  SetSpeed(6);
}

