public static void DemoSequence(int dt) {
  double angle = GetAngle();
  double height = GetHeight();

  if (angle < 134 && step == 0) {
    if (angle < 120) { SetSpeed(40); } else { SetSpeed(26); }
    RotateTo(135);
    return;
  }
  if (step == 0) { step = 1; }

  if (height < 1.5 && step == 1) {
    if (height < 1.3) { SetSpeed(24); } else { SetSpeed(12); }
    LiftTo(1.5);
    return;
  }
  if (step == 1) { step = 2; }

  if (angle > 46 && step == 2) {
    if (angle > 70) { SetSpeed(28); } else { SetSpeed(18); }
    RotateTo(45);
    return;
  }
  if (step == 2) { step = 3; }

  if (height < 2.0 && step == 3) {
    if (height < 1.85) { SetSpeed(18); } else { SetSpeed(10); }
    LiftTo(2.0);
    return;
  }
  SetSpeed(6);
}

