public static void Setup() {
  ResetCar();
  SetDriveSpeed(1.5);
  SetTurnSpeed(200);
  int stage = 0;
  bool checkpointA = false;
  bool checkpointB = false;
}

public static void Tick(int dt) {
  NavigateAdvanced();
}

public static void NavigateAdvanced() {
  if (!checkpointA && GetPosY() < 4.6 && GetPosX() >= 5.4) { checkpointA = true; }
  if (checkpointA && !checkpointB && GetPosY() >= 7.4 && GetPosX() >= 7.4) { checkpointB = true; }
  if (stage == 0) { DriveForward(7.0); stage = 1; return; }
  if (stage == 1 && GetPosX() >= 8.4) { TurnTo(90); stage = 2; return; }
  // fortsæt med TurnTo og DriveForward for hvert gangstykke
}

